function correctGameModal(id){if(dirty){toast('Сначала сохраните или отмените ввод.',true);return;}const r=current.rounds.find(r=>r.games.some(g=>g.id===id)),g=r?.games.find(g=>g.id===id);if(!g)return;const impact=correctionImpact(current,r.number);modal('Исправить счёт',`<form id="score-correction"><p class="confirm-detail">${esc(impactText(impact))}</p>${g.players.map((id,i)=>`<label class="field">${esc(names(id))}<input name="score${i}" required inputmode="decimal" value="${esc(g.scores?raw(g.scores[i]):'')}" aria-label="Новый счёт: ${esc(names(id))}"></label>`).join('')}${modalButtons('Сохранить исправление',true)}</form>`,async fd=>{const ok=await mutate({type:'results',round:r.number,game:g.id,scores:g.players.map((_,i)=>fd.get('score'+i)),confirm:true,resetFollowing:true},{message:'Счёт исправлен'});if(ok){view='rounds';selectedRound=r.number;writeRoute();render();}return ok;});}
function saveSettings(values){const divisor=scoringDivisor(values.scoreDivisor);if(divisor!==scoringDivisor(current)&&(current.rounds.length>1||current.finals.length)){confirmModal('Изменить делитель счёта?',`Очки будут пересчитаны: делитель ${scoringDivisor(current)} → ${divisor}. Счёт первого круга сохранится. Последующие круги и финалы будут отменены; их данные останутся в истории.`,async()=>await mutate({type:'settings',...values,scoreDivisor:divisor,confirm:true},{message:'Настройки сохранены'}),{label:'Пересчитать очки'});return;}return mutate({type:'settings',...values,scoreDivisor:divisor});}
