async function prepareResultImage(stage){
 const state=imageShare;if(!state?.snapshot)return;
 const generation=(state.generation??0)+1;state.generation=generation;state.stage=stage;
 for(const item of state.images)URL.revokeObjectURL(item.url);state.images=[];
 $('#result-image-preview').replaceChildren();$('#result-image-paging').hidden=true;$('#result-image-text').hidden=true;
 for(const b of $('#modal').querySelectorAll('.image-actions button'))b.disabled=true;
 $('#result-image-status').className='subtle';$('#result-image-status').textContent='Готовим картинку…';
 try{
   const card=resultCard(state.snapshot,stage),images=await renderResultImages(card);
   if(imageShare!==state||state.generation!==generation||!$('#modal').open)return;
   state.card=card;state.page=0;state.images=images.map(item=>({...item,url:URL.createObjectURL(item.blob)}));
   state.textBlocks=telegramTextBlocks(card);state.textPage=0;state.textCopy=null;$('#modal [data-action=text-copy]').disabled=false;showResultTextBlock();
   $('#result-image-text').hidden=false;
   for(const b of $('#modal').querySelectorAll('.image-actions button'))b.disabled=false;
   $('#result-image-status').textContent=images.length>1?`Изображений: ${images.length}. Скопируйте или скачайте каждое — все игроки включены.`:'Только сохранённые результаты. Картинка не содержит приватных данных.';
   showResultImagePage();
 }catch(error){if(imageShare===state&&state.generation===generation){$('#result-image-status').className='inline-error';$('#result-image-status').textContent=error.message;}}
}
function showResultImagePage(){const state=imageShare,item=state?.images[state.page];if(!item)return;$('#result-image-preview').innerHTML=`<img src="${item.url}" width="${item.width}" height="${item.height}" alt="${esc(state.card.name+' · '+state.card.stage)} · изображение ${state.page+1} из ${state.images.length}">`;$('#result-image-paging').hidden=state.images.length<2;$('#result-image-page').textContent=`${state.page+1} / ${state.images.length}`;$('#modal [data-action=image-prev]').disabled=state.page===0;$('#modal [data-action=image-next]').disabled=state.page===state.images.length-1;}
function changeImagePage(delta){const state=imageShare;if(!state?.images.length)return;state.page=Math.max(0,Math.min(state.images.length-1,state.page+delta));showResultImagePage();}
function showResultTextBlock(){
 const state=imageShare;if(!state?.textBlocks?.length)return;
 $('#result-text-block').value=state.textBlocks[state.textPage];$('#result-text-block').scrollTop=0;
 $('#result-text-paging').hidden=state.textBlocks.length<2;$('#result-text-page').textContent=`${state.textPage+1} / ${state.textBlocks.length}`;
 $('#modal [data-action=text-prev]').disabled=state.textPage===0;$('#modal [data-action=text-next]').disabled=state.textPage===state.textBlocks.length-1;
 $('#result-text-status').textContent=state.textBlocks.length>1?'Длинные результаты разделены на сообщения для Telegram. Скопируйте каждый блок.':'Весь этап — одним текстовым блоком, как на картинке.';
}
function changeTextBlock(delta){const state=imageShare;if(!state?.textBlocks?.length)return;state.textPage=Math.max(0,Math.min(state.textBlocks.length-1,state.textPage+delta));showResultTextBlock();}
async function copyResultText(){
 const state=imageShare,text=state?.textBlocks?.[state.textPage];if(!text||state.textCopy)return;
 const operation={};state.textCopy=operation;const generation=state.generation,page=state.textPage,button=$('#modal [data-action=text-copy]');button.disabled=true;
 const active=()=>imageShare===state&&state.generation===generation&&state.textPage===page;
 try{
   if(!navigator.clipboard?.write||!window.ClipboardItem)throw Error('plain-text');
   await navigator.clipboard.write([new ClipboardItem({'text/plain':new Blob([text],{type:'text/plain'}),'text/html':new Blob([`<html><body><pre>${esc(text)}</pre></body></html>`],{type:'text/html'})})]);
   if(active())$('#result-text-status').textContent='Текстовый блок скопирован. Вставьте его в Telegram.';
 }catch{
   try{await navigator.clipboard.writeText(text);if(active())$('#result-text-status').textContent='Текст скопирован. В Telegram при необходимости выберите «Моноширинный».';}
   catch{if(active()){const field=$('#result-text-block');field.focus();field.select();$('#result-text-status').textContent='Браузер не разрешил копирование. Скопируйте выделенный блок вручную.';}}
 }finally{if(state.textCopy===operation){state.textCopy=null;if(imageShare===state&&state.generation===generation)button.disabled=false;}}
}
async function copyResultImage(){
 const state=imageShare,item=state?.images[state.page];if(!item||state.copying)return;state.copying=true;const generation=state.generation,page=state.page,button=$('#modal [data-action=image-copy]');button.disabled=true;
 try{if(!navigator.clipboard?.write||!window.ClipboardItem)throw Error('unsupported');await navigator.clipboard.write([new ClipboardItem({'image/png':item.blob})]);if(imageShare===state&&state.generation===generation){$('#result-image-status').className='subtle';$('#result-image-status').textContent=`Картинка${state.images.length>1?' '+(page+1)+' / '+state.images.length:''} скопирована. Вставьте её в Telegram.`;}}
 catch{if(imageShare===state&&state.generation===generation){$('#result-image-status').className='subtle';$('#result-image-status').textContent='Браузер не разрешил копирование. Нажмите «Скачать PNG» и отправьте файл в Telegram.';$('#modal [data-action=image-download]').focus();}}
 finally{state.copying=false;if(imageShare===state&&state.generation===generation)button.disabled=false;}
}
function downloadResultImage(){const state=imageShare,item=state?.images[state.page];if(!item)return;const link=document.createElement('a');link.href=item.url;link.download=state.card.filename+(state.images.length>1?'-'+(state.page+1):'')+'.png';link.click();}
function exportPreview(){let rows=[];try{rows=ratingRows(current).slice(0,6);}catch{}const example=!rows.length;if(example)rows=ratingRows({date:localToday(),players:[1,2,3,4].map(i=>({id:'sample'+i,name:'Пример Игрок '+i})),rounds:[{games:[{players:['sample1','sample2','sample3','sample4'],scores:[100000,70000,70000,0]}]}],finals:[]});return `<details class="export-example"><summary>Пример для Google Таблиц</summary><p class="subtle">${example?'Вымышленные данные одного боя.':'Первые шесть строк вашего экспорта.'} Один бой — шесть строк, четыре столбца A:D. Передаётся исходный счёт.</p><div class="table-wrap"><table class="export-preview"><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><a href="/export-example.tsv" download="primer-dlya-google-tablits.tsv">Скачать пример · TSV</a></details>`;}
function finalsModal(){const rows=resultRows().filter(p=>p.active!==false);modal('Выбрать участников финалов',`<form id="final-assignment"><p>Выберите любое число участников из состава турнира. Каждый игрок — только в одном финале. Малый финал необязателен.</p><div class="final-counts" role="status"><span id="grand-count">Грандфинал: 0</span><span id="small-count">Малый финал: 0</span></div><div class="final-assignment-list">${rows.map(p=>`<label class="final-assignment-row"><span><small>${p.rank}</small>${esc(p.name)}</span><select name="final-${p.id}" aria-label="Финал: ${esc(p.name)}"><option value="">Не участвует</option><option value="grand">Грандфинал</option><option value="small">Малый финал</option></select></label>`).join('')}</div>${modalButtons('Сформировать финалы')}</form>`,async fd=>{const grand=rows.filter(p=>fd.get('final-'+p.id)==='grand').map(p=>p.id),small=rows.filter(p=>fd.get('final-'+p.id)==='small').map(p=>p.id);if(!grand.length)throw Error('Выберите хотя бы одного участника грандфинала.');const ok=await mutate({type:'finals',groups:small.length?[grand,small]:[grand]},{message:'Финалы сформированы'});if(ok){view='finals';writeRoute();render();}return ok;});updateFinalCounts();}
function updateFinalCounts(){const form=$('#final-assignment');if(!form)return;const counts={grand:0,small:0};for(const select of form.querySelectorAll('select'))if(select.value)counts[select.value]++;$('#grand-count').textContent=`Грандфинал: ${counts.grand}`;$('#small-count').textContent=`Малый финал: ${counts.small}`;form.querySelector('button[type=submit]').disabled=counts.grand===0;}
function rollbackModal(keep=current.rounds.length-1){const max=current.rounds.length;keep=Math.max(0,Math.min(keep,max));const options=Array.from({length:max+1},(_,i)=>i).filter(i=>i<max||current.finals.length);modal('Отменить последующие игры',`<form><p>Чтобы исправить старый результат, нужно явно отменить игры, которые уже зависят от него. Сохранённые ранее действия останутся в журнале.</p><label class="field">Что сохранить<select name="keep" id="rollback-keep">${options.map(i=>`<option value="${i}" ${i===keep?'selected':''}>${i===0?'Только регистрацию':i===1?'Круг 1':'Круги 1–'+i}</option>`).join('')}</select></label><p class="confirm-detail" id="rollback-summary"></p><p class="field-hint">Перед отменой можно закрыть окно и скачать резервную копию. Автоматического восстановления отменённых игр нет.</p>${modalButtons('Отменить указанные игры',true)}</form>`,async fd=>{const keep=Number(fd.get('keep'));const ok=await mutate({type:'rollback',keep,confirm:true},{message:'Последующие игры отменены'});if(ok){view='rounds';selectedRound=keep||1;writeRoute();render();}return ok;});updateRollbackSummary();}
function deleteTournamentModal(tournament=current){if(!tournament.canEdit||busy||modalPending)return;if(dirty){toast('Сначала сохраните или отмените ввод.',true);return;}const {id,revision}=tournament;confirmModal('Удалить турнир?','Турнир и все его результаты будут удалены навсегда. Ссылки и восстановление из резервной копии перестанут работать.',async()=>{await api('/tournaments/'+id+'/delete',{method:'POST',body:JSON.stringify({revision,confirm:true})});if(current.id===id){discardDrafts();current=emptyTournament();selectedRound=1;}privateKeys.delete(id);tournaments=tournaments.filter(t=>t.id!==id);try{sessionStorage.removeItem('svoyak-draft:'+id);if(localStorage.getItem('svoyak-active')===id)localStorage.removeItem('svoyak-active');}catch{}if(pendingRecovery?.id===id)pendingRecovery=null;if(entry.id===id)entry={id:null,query:'',selected:new Map(),open:false,active:0,error:''};session.hasOwnerSession=tournaments.length>0;view='tournaments';query='';filter='all';connection='ok';writeRoute(true);closeModal(true);render();toast('Турнир удалён');return true;},{label:'Удалить'});}
function updateRollbackSummary(){const el=$('#rollback-summary'),select=$('#rollback-keep');if(!el||!select)return;const keep=Number(select.value),removed=current.rounds.slice(keep);const saved=removed.flatMap(r=>r.games).filter(g=>g.scores).length;el.textContent=`Будут отменены: ${removed.length?'круги '+removed.map(r=>r.number).join(', '):'только финалы'}${removed.length&&current.finals.length?' и все финалы':''}. Записанных результатов в отменяемых кругах: ${saved}. ${keep?'Круги 1–'+keep+' и их результаты сохранятся.':'Регистрация игроков сохранится.'}`;}
async function handleAction(action){if(busy||modalPending&&action!=='close')return;if(!canEdit()&&!['close','new','share','copy-link','copy-results','copy-rating','games-csv','export','print','csv','retry','refresh-results','result-image','image-copy','image-download','image-prev','image-next','image-retry','text-copy','text-prev','text-next','text-copy','text-prev','text-next'].includes(action)){toast('Это режим просмотра. Изменения доступны только организатору.',true);return;}if(dirty&&!['close','csv','games-csv','json','print','export','copy-rating','share','copy-link','discard-drafts','next-missing','result-image','image-copy','image-download','image-prev','image-next','image-retry'].includes(action)){toast('Сначала сохраните введённые изменения.',true);return;}switch(action){case'close':closeModal();break;case'discard-drafts':confirmModal('Отменить несохранённый ввод?','Черновики этой вкладки будут удалены. Сохранённые на сервере результаты останутся без изменений.',()=>{discardDrafts();render();return true;},{label:'Отменить ввод'});break;case'next-missing':jumpToMissing();break;case'refresh-results':await refreshResults();break;case'new':newModal();break;case'go-players':navigate('participants');break;case'add-selected':await addSelectedPlayers();break;case'share':linkModal(false);break;case'private-link':linkModal(true);break;case'copy-link':{const input=$('#share-link');try{await navigator.clipboard.writeText(input.value);toast('Ссылка скопирована');}catch{input.focus();input.select();toast('Скопируйте выделенную ссылку вручную');}break;}case'copy-results':await copyResults();break;case'register':registrationModal();break;case'retry':await init();break;case'go-rounds':navigate('rounds');break;case'reshuffle':reshuffleModal();break;case'draw':drawModal();break;case'pending-groups':rosterChangeModal();break;
 case'result-image':await resultImageModal();break;case'image-copy':await copyResultImage();break;case'text-copy':await copyResultText();break;case'text-prev':changeTextBlock(-1);break;case'text-next':changeTextBlock(1);break;case'image-download':downloadResultImage();break;case'image-prev':changeImagePage(-1);break;case'image-next':changeImagePage(1);break;case'image-retry':await resultImageModal(imageShare?.stage);break;
 case'print':if(dirty){toast('Сначала сохраните введённые результаты.',true);return;}window.print();break;
 case'csv':csvExport();break;case'games-csv':download('all-games.csv',gamesCSV(current),'text/csv;charset=utf-8');break;case'json':{const backup=await api('/tournaments/'+current.id+'/backup');download('svoyak-backup.json',JSON.stringify(backup,null,2),'application/json');break;}
 case'export':{let games=0,error='';try{games=ratingRows(current).length/6;}catch(e){error=e.message;}const excluded=ratingExclusions(current),total=ratingGames(current).length;modal('Экспорт результатов',`<div class="export-image-entry"><div><h3>В Telegram</h3><p class="subtle">Результаты круга или финалов картинкой.</p></div>${resultImageButton()}</div><div class="rating-export"><h3>Для рейтинга</h3><p>Вставьте в лист <strong>Data</strong>, в первый свободный блок <strong>A:D</strong>, только значения. Столбцы <strong>E:AK</strong> не трогайте; формулы должны покрывать новые строки.</p><p class="export-warning">Не вставляйте повторно: это задвоит результаты. События в таблице объединяются по дате турнира.</p>${exportPreview()}${excluded.length?`<p class="export-warning">Не включены в Data: ${excluded.map(g=>`${esc(g.label)} (${g.players} игроков)`).join(', ')}. В этом формате только четыре места. Все участники и счета есть в CSV «Все бои».</p>`:''}${error?`<p class="inline-error">${esc(error)}</p>`:`<p class="subtle">${games} сыгранных боёв${games+excluded.length<total?' · бои без счёта не включены':''}</p>`}<button class="primary" data-action="copy-rating" ${error||!games?'disabled':''}>Скопировать для рейтинга</button></div><div class="export-secondary"><button data-action="games-csv">${icon('download')}Все бои · CSV</button><button data-action="csv">${icon('download')}Скачать итоговую таблицу · CSV</button><button data-action="print">${icon('print')}Печать</button></div>`);break;}
 case'copy-rating':{const text=ratingTSV(current);try{await navigator.clipboard.writeText(text);toast('Скопировано. Вставьте значения в Data A:D.');}catch{modal('Данные для рейтинга',`<p>Скопируйте и вставьте только в Data A:D.</p><textarea readonly rows="10" aria-label="Данные для рейтинга">${esc(text)}</textarea><div class="actions"><button data-action="close">Готово</button></div>`);$('#modal textarea')?.select();}break;}
 case'import-csv':filePicker('.txt,.csv',text=>{let lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).map(l=>l.trim()).filter(Boolean);if(/^(имя|игрок|name|participant)$/i.test(lines[0]))lines.shift();if(lines.some(l=>/[;\t]/.test(l)))throw Error('Импортируйте один столбец с именами, по одному игроку в строке.');registrationModal(lines.map(l=>l.replace(/^"|"$/g,'').replace(/""/g,'"')).join('\n'));});break;
 case'finals':finalsModal();break;
 case'finish':confirmModal('Завершить турнир','Итоговые результаты будут зафиксированы. При необходимости турнир можно снова открыть в настройках.',async()=>await mutate({type:'finish'},{message:'Турнир завершён'}));break;
 case'reopen':confirmModal('Открыть редактирование','Результаты снова станут доступны для исправления. История сохранится.',async()=>await mutate({type:'reopen'}));break;
 case'archive':confirmModal(current.archived?'Восстановить турнир':'Архивировать турнир',current.archived?'Турнир вернётся в работу. Все результаты сохранятся.':'Турнир переместится в архив. Ссылка для просмотра перестанет работать до восстановления.',async()=>await mutate({type:'archive'}));break;
 case'delete-tournament':deleteTournamentModal();break;
 case'rollback':rollbackModal();break;
 case'swap':swapModal();break;
 case'restore':filePicker('.json',async text=>{const data=JSON.parse(text);if(data.format!=='svoyak-v1')throw Error('Это не резервная копия приложения.');modal('Восстановить турнир',`<form><p>Копия «${esc(data.tournament?.name)}» будет восстановлена как отдельный турнир. Существующие данные сохранятся.</p>${modalButtons('Восстановить копию')}</form>`,async()=>{const result=await api('/restore',{method:'POST',body:JSON.stringify(data)});const t=result.tournament;privateKeys.set(t.id,result.managementKey);session.hasOwnerSession=true;tournaments.unshift(t);current=t;view='standings';selectedRound=t.rounds.length||1;remember(t.id);discardDrafts();writeRoute();closeModal(true);render();toast('Турнир восстановлен');});});break;
 }}
async function refreshResults(){if(canEdit()||!current.id||current.id==='unavailable'||document.hidden||$('#modal').open)return;try{const next=await api('/tournaments/'+current.id);const changed=JSON.stringify(next)!==JSON.stringify(current);current=next;if(changed)render();connection='ok';updateSync();}catch(error){if(error.status===404){current=noTournament();view='unavailable';connection='ok';render();return;}connection='error';updateSync();}}
setInterval(()=>{if(!canEdit())refreshResults();},15000);
function jumpToMissing(){const r=current.rounds.find(r=>r.number===selectedRound);const missing=r?.games.find(g=>!g.scores);if(!missing)return;filter='all';render();const form=document.querySelector(`form[data-game="${missing.id}"]`);form?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});form?.querySelector('input:not([readonly])')?.focus({preventScroll:true});}
document.addEventListener('click',async e=>{
 if(e.target.closest('[data-skip]')){e.preventDefault();$('#main-content')?.focus();return;}
 if(!e.target.closest('.entry-search')){entry.open=false;updatePicker();}if(!e.target.closest('.more-menu,.row-menu'))document.querySelectorAll('.more-menu[open],.row-menu[open]').forEach(menu=>menu.open=false);
 const summary=e.target.closest('.more-menu>summary,.row-menu>summary');if(summary){const currentMenu=summary.parentElement;document.querySelectorAll('.more-menu[open],.row-menu[open]').forEach(menu=>{if(menu!==currentMenu)menu.open=false;});}const b=e.target.closest('button,a[data-view]');if(!b||b.disabled||busy)return;
 if(b.matches('a'))e.preventDefault();b.closest('.more-menu,.row-menu')?.removeAttribute('open');
 if(b.dataset.pickPlayer){if(b.getAttribute('aria-disabled')!=='true'){selectPending(b.dataset.pickPlayer);entry.query='';entry.active=0;const input=$('#player-entry');if(input){input.value='';input.focus();}updatePicker();}return;}
 if(b.dataset.removePending){entry.selected.delete(normalizeName(b.dataset.removePending));updatePicker();return;}
 if(b.hasAttribute('data-result-image')){await resultImageModal(b.dataset.resultImage||null);return;}
 if(b.dataset.resultsMode){resultMode={id:current.id,value:b.dataset.resultsMode};sort='rank';render();return;}
 if(b.dataset.view){navigate(b.dataset.view);return;}
 if(b.dataset.action){try{await handleAction(b.dataset.action);}catch(err){toast(err.message,true);}return;}
 if(b.dataset.stage){const n=Number(b.dataset.stage);if(n===0)navigate('participants');else if(n===4)navigate('finals');else if(current.rounds[n-1])navigate('rounds',{round:n});else toast('Этот круг ещё не сформирован.');return;}
 if(b.dataset.round){navigate('rounds',{round:Number(b.dataset.round)});return;}
 if(b.dataset.sort){if(sort===b.dataset.sort)sortDirection=sortDirection==='asc'?'desc':'asc';else{sort=b.dataset.sort;sortDirection=sort==='name'?'asc':'desc';}render();return;}
 if(b.dataset.open){await openTournament(b.dataset.open);return;}
 if(b.dataset.deleteTournament){const tournament=tournaments.find(t=>t.id===b.dataset.deleteTournament);if(tournament?.canEdit)deleteTournamentModal(tournament);return;}
 if(b.dataset.tournamentFilter){tournamentFilter=b.dataset.tournamentFilter;query='';render();return;}
 if(!canEdit())return;
 if(b.dataset.markMissed){const r=current.rounds.at(-1),ids=new Set(r.missed??[]);if(ids.has(b.dataset.markMissed))ids.delete(b.dataset.markMissed);else ids.add(b.dataset.markMissed);rosterChangeModal({missedIds:[...ids]});return;}
 if(b.dataset.addChair||b.dataset.removeChair){const game=findGame(b.dataset.addChair??b.dataset.removeChair);if(!game)return;const ok=await mutate({type:'chairs',game:game.id,count:chairCount(game)+(b.dataset.addChair?1:-1)},{message:b.dataset.addChair?'Стул добавлен':'Стул убран'});if(ok)document.querySelector(`[data-add-chair="${CSS.escape(game.id)}"]:not(:disabled)`)?.focus({preventScroll:true});return;}
 if(b.dataset.restorePlayer){rosterChangeModal({restoreIds:[b.dataset.restorePlayer]});return;}
 if(b.dataset.editGame){correctGameModal(b.dataset.editGame);return;}
 if(b.dataset.correctRound){if(dirty){toast('Сначала сохраните или отмените ввод.',true);return;}rollbackModal(Number(b.dataset.correctRound));return;}
 if(b.dataset.editPlayer){const p=current.players.find(p=>p.id===b.dataset.editPlayer);modal('Исправить имя',`<form><label class="field">Имя игрока<input name="name" required maxlength="100" value="${esc(p.name)}"></label><p class="field-hint">Записанные бои остаются связанными с этим игроком.</p>${modalButtons()}</form>`,async fd=>await mutate({type:'rename',id:p.id,name:fd.get('name')}));return;}
 if(b.dataset.removePlayer){const p=current.players.find(p=>p.id===b.dataset.removePlayer);if(current.rounds.length){rosterChangeModal({removeIds:[p.id]});return;}confirmModal('Удалить участника',`Игрок «${esc(p.name)}» будет удалён из регистрации.`,async()=>await mutate({type:'remove',id:p.id}));}
});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!form.dataset.form)return;e.preventDefault();if(!canEdit()||busy)return;
 const fd=new FormData(form);if(form.dataset.form==='settings'){try{await saveSettings(Object.fromEntries(fd));}catch(error){toast(error.message,true);}return;}
 if(!validateScoreForm(form))return;
 const final=form.dataset.form==='final-result',g=findGame(form.dataset.game);
 const action={type:final?'finalResults':'results',game:g.id,scores:g.players.map((_,i)=>fd.get('score'+i)),...(!final?{round:Number(form.dataset.round)}:{})};
 const save=async()=>{const ok=await mutate(action,{message:'Результат сохранён',formId:g.id});if(ok){const forms=[...document.querySelectorAll('form[data-form="result"],form[data-form="final-result"]')];const next=forms.find(f=>!findGame(f.dataset.game)?.scores);next?.querySelector('input:not([readonly])')?.focus();}return ok;};
 if(g.scores)confirmModal('Исправить записанный результат',`Старый счёт: ${g.scores.map(raw).join(' / ')}.<br>Новый счёт: ${action.scores.map(esc).join(' / ')}.<br>${final?'Места будут пересчитаны по новому счёту. ':''}Изменение будет записано в историю.`,async()=>{action.confirm=true;return await save();},{label:'Сохранить исправление'});else await save();
});
document.addEventListener('input',e=>{
 if(e.target.matches('#roster-change [name=sizes]'))updateRosterImpact();
 if(e.target.closest('#draw-options'))updateDrawSizes();
 if(e.target.id==='player-entry'){entry.query=e.target.value;entry.open=true;entry.active=-1;entry.error='';updatePicker();}
 const form=e.target.closest('form[data-form="result"],form[data-form="final-result"]');if(form&&canEdit())captureGameDraft(form);
 if(e.target.closest('form[data-form="settings"]')){const values=Object.fromEntries(new FormData(e.target.closest('form')));settingsDraft=['name','date','location','scoreDivisor'].some(k=>String(values[k])!==String(k==='scoreDivisor'?scoringDivisor(current):current[k]??''))?values:null;refreshDirty();}
 if(e.target.id==='participant-search'){query=e.target.value;$('#participant-rows').innerHTML=participantRows();}
 if(e.target.id==='tournament-search'){query=e.target.value;const list=tournaments.filter(t=>(tournamentFilter==='archived'?t.archived:!t.archived)&&t.name.toLocaleLowerCase('ru').includes(query.toLocaleLowerCase('ru')));$('#tournament-items').innerHTML=tournamentItems(list);}
 if(e.target.matches('#modal textarea[name="names"]')){const n=e.target.value.split(/\r?\n/).filter(s=>s.trim()).length;$('#registration-count').textContent=`Добавляется: ${n} · свободных мест после добавления: ${40-activePlayers(current).length-n}`;}
});
document.addEventListener('change',e=>{
 if(e.target.id==='result-image-stage'){prepareResultImage(e.target.value);return;}
 if(e.target.matches('[data-appearance]')){window.SvoyakAppearance?.set(e.target.value);toast('Тема оформления изменена');return;}
 if(e.target.id==='game-filter'){filter=e.target.value;render();}
 if(e.target.closest('form[data-form="final-result"]'))captureGameDraft(e.target.closest('form'));
 if(e.target.closest('#final-assignment'))updateFinalCounts();
 if(e.target.closest('#roster-change'))updateRosterImpact(true);
 if(e.target.closest('#swap-players'))updateSwapImpact();
 if(e.target.id==='rollback-keep')updateRollbackSummary();
});
document.addEventListener('focusin',e=>{if(e.target.id==='player-entry'&&entry.query.trim()){entry.open=true;updatePicker();}});
document.addEventListener('paste',e=>{if(e.target.id==='player-entry'){const text=e.clipboardData?.getData('text')??'';if(/[\r\n]/.test(text)){e.preventDefault();for(const name of text.split(/\r?\n/).filter(s=>s.trim()))selectPending(name);entry.query='';e.target.value='';entry.open=false;updatePicker();}}});
document.addEventListener('keydown',e=>{
 const correction=e.target.closest('#score-correction');if(correction&&e.key==='Enter'){e.preventDefault();const controls=[...correction.querySelectorAll('input')],next=controls[controls.indexOf(e.target)+1];if(!(e.ctrlKey||e.metaKey)&&next){next.focus();next.select();}else correction.requestSubmit();return;}
 if(e.key==='Escape'){const menu=document.querySelector('.more-menu[open],.row-menu[open]');if(menu){menu.open=false;menu.querySelector('summary')?.focus();e.preventDefault();return;}}
 if(e.target.id==='player-entry'){const choices=[...document.querySelectorAll('#player-options button:not([aria-disabled="true"])')];if(e.key==='Escape'){entry.open=false;updatePicker();return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();entry.open=true;entry.active=Math.max(0,Math.min(choices.length-1,entry.active+(e.key==='ArrowDown'?1:-1)));e.target.setAttribute('aria-activedescendant',choices[entry.active]?.id??'');choices.forEach((option,i)=>option.classList.toggle('focused',i===entry.active));return;}if(e.key==='Enter'){e.preventDefault();if(e.ctrlKey||e.metaKey){addSelectedPlayers();return;}if(!entry.open&&!entry.query.trim())return;const name=choices[entry.active<0?0:entry.active]?.dataset.pickPlayer??entry.query;if(name)selectPending(name);entry.query='';e.target.value='';entry.open=false;updatePicker();return;}}
 const form=e.target.closest('form[data-form="result"],form[data-form="final-result"]');if(!form||!canEdit()||busy)return;
 if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();form.requestSubmit();return;}
 if(e.key==='Enter'&&e.target.matches('.player-row input,.player-row select')){e.preventDefault();const controls=[...form.querySelectorAll('.player-row input:not([readonly]),.player-row select:not([disabled])')];const next=controls[controls.indexOf(e.target)+1];if(next){next.focus();next.select?.();}else form.requestSubmit();}
});
$('#modal').addEventListener('cancel',e=>{if(modalPending){e.preventDefault();return;}modalOnCancel?.();modalOnCancel=null;});
$('#modal').addEventListener('close',()=>{disposeResultShare();if(modalReturnFocus?.isConnected)modalReturnFocus.focus();modalReturnFocus=null;});
window.addEventListener('hashchange',()=>{if(captureRecovery())recoveryModal();});
window.addEventListener('popstate',()=>{const route=readRoute();if(route.id&&route.id!==current.id){if(dirty){const previous=routeURL();confirmModal('Отменить несохранённый ввод?','При переходе черновик будет отменён.',async()=>{discardDrafts();await openTournament(route.id,{fromHistory:true,targetView:route.view,round:route.round});return true;},{onCancel:()=>history.pushState(null,'',previous)});}else openTournament(route.id,{fromHistory:true,targetView:route.view,round:route.round});}else if(route.view)navigate(route.view,{round:route.round||selectedRound,fromHistory:true});});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!canEdit())refreshResults();});
window.addEventListener('beforeunload',e=>{persistDrafts();if(dirty){e.preventDefault();e.returnValue='';}});
init();
